//! Binary **interaction parameters** and departure-function assignments for
//! the multi-fluid mixture model -- CoolProp's `mixture_binary_pairs.json` +
//! `mixture_departure_functions.json`, hardcoded.
//!
//! **840** of CoolProp's 888 binary pairs are ported (the rest
//! touch a component outside this crate's 137 ported pure fluids -- see
//! `dev/regen_mixture_all.py`'s module doc). Data lives in `data_<n>.rs`
//! (5 chunks, generated by `dev/gen_mixture.py` / `dev/regen_mixture_all.py`
//! -- do not edit those by hand); this file is hand-maintained.
//!
//! A pair **absent** from the table is treated as ideal Lorentz-Berthelot
//! combining (`β = γ = 1`, `F = 0`) by
//! [`super::reducing`]/[`super::Mixture::residual_derivs`] -- matching
//! CoolProp's own default for binary pairs it has no fitted data for, not an
//! error condition. [`lookup`] returning `None` is the normal, common case.

mod data_0;
mod data_1;
mod data_2;
mod data_3;
mod data_4;

use crate::fluid::Fluid;
use crate::mixtures::departure::DepartureTerm;

/// The interaction data for one unordered pair of components `(i, j)`.
///
/// Holds the Lorentz-Berthelot reducing-function parameters ([`reducing`])
/// and the departure-function scaling `F_{ij}` + term list ([`departure`]).
///
/// [`reducing`]: super::reducing
/// [`departure`]: super::departure
#[derive(Debug, Clone, Copy)]
pub struct BinaryPair {
    /// First component.
    pub a: Fluid,
    /// Second component.
    pub b: Fluid,
    /// Reducing-temperature parameters `(β^T, γ^T)`.
    pub beta_gamma_t: (f64, f64),
    /// Reducing-volume parameters `(β^v, γ^v)`.
    pub beta_gamma_v: (f64, f64),
    /// Departure-function scaling `F_{ij}` (0 ⇒ no departure term, ideal mixing).
    pub f_departure: f64,
    /// Departure-function term list (empty when `f_departure == 0`).
    pub departure_terms: &'static [DepartureTerm],
}

/// Every data chunk, searched in turn by [`lookup`] (840 pairs total).
static CHUNKS: &[&[BinaryPair]] = &[
    data_0::DATA,
    data_1::DATA,
    data_2::DATA,
    data_3::DATA,
    data_4::DATA,
];

/// Look up the interaction data for the unordered pair `(a, b)`.
///
/// Returns `None` when the pair is absent from the table -- the common
/// case, treated as ideal combining (`β=γ=1`, `F=0`) by the callers, per
/// the module doc.
pub fn lookup(a: Fluid, b: Fluid) -> Option<&'static BinaryPair> {
    all().find(|p| (p.a == a && p.b == b) || (p.a == b && p.b == a))
}

/// Every ported binary pair, for enumeration (840 in total).
pub fn all() -> impl Iterator<Item = &'static BinaryPair> {
    CHUNKS.iter().flat_map(|chunk| chunk.iter())
}
